insert into cases (case_id, idea_id, case_question, case_answer) values
  (21, 'BACKEND_PURPOSE', 'A ticket-booking site puts its refund rules only in browser JavaScript, and the rules change every month. What could go wrong, and how could a backend help?', 'Browser code can be inspected and changed by users. A backend can centralize the refund rules, apply them consistently, and allow updates without relying on each browser.'),
  (22, 'API_REQUEST', 'A delivery app asks the server for the status of order 5310, but the server replies that it does not know which order is meant. What should the request carry?', 'The request must carry the order identifier, 5310, for example in the URL path or a query parameter, so the server knows which order to look up.'),
  (23, 'API_AUTH', 'A weather website calls a paid weather API from its frontend JavaScript, with the API key written in the code. How should it be redesigned so visitors cannot get the key?', 'The website should send the request through its backend, which keeps the key on the server and makes the authorized call to the weather API.'),
  (24, 'PERSISTENCE', 'A quiz app shows each learner''s score history, but the history is empty every time the server restarts. What should the app do so the history survives?', 'The history is kept only in temporary memory, which is lost when the server restarts. Save each attempt in durable storage such as a database, and retrieve the saved attempts when the history is shown.'),
  (25, 'FOREIGN_KEY_MANY_SIDE', 'A learner has answered eight cases. A developer adds columns attempt_1 to attempt_8 to the learners table. What design would work for any number of attempts?', 'Store each attempt as a separate row in an attempts table, with a learner_id foreign key referencing the learner.'),
  (26, 'EVENT_ROWS', 'A teacher wants to see how many attempts each learner made last week, but all attempts are stored as one long text field per learner. Why is that a problem, and what should change?', 'Each attempt should be stored as its own row so it can be filtered by date, counted, and analyzed independently.'),
  (27, 'DATA_LOCATION', 'A chat app keeps each learner''s last message in a server variable so it can show it again later. After a deploy, the messages are gone. Should the app rely on that variable? Explain.', 'No. A server variable is temporary and is lost on a restart or deploy. The app should save the data in durable storage such as a database so it survives a restart.'),
  (28, 'HTTP_RESPONSE', 'An API creates a new learner account. How should it tell the client that the account was created?', 'Return an appropriate success status code, such as HTTP 201 Created, and optionally the new account''s identifier.'),
  (29, 'REFERENTIAL_INTEGRITY', 'A developer deletes a test learner, but some attempts still point to learner_id 42. What database rule should stop attempts from pointing to a learner that does not exist?', 'A foreign key constraint from attempts.learner_id referencing learners.id should reject attempts whose learner does not exist.'),
  (30, 'RETRY_GAP', 'A teacher wants to know whether learners'' second tries fix the difficulty they had. Retries are saved, but nothing records which difficulty each retry was for. What should change?', 'Each retry attempt should reference the gap it addresses, for example with a gap_id. This link connects the original difficulty to the retry and its result, so the teacher can trace whether it was fixed.')
